  // The rules of the game live in lib/ (docs/ARCHITECTURE.md): economy.js,
  // community-table.js, seasons.js, acts.js and wildlife.js decide; this class
  // keeps the words, pictures and sounds, and asks them.
  rules={economy:window.PermacultureEconomy,table:window.PermacultureCommunityTable,seasons:window.PermacultureSeasons,acts:window.PermacultureActs,wildlife:window.PermacultureWildlife};
  // A rule table and the words for it, keyed by the same ids, joined into the
  // table the game reads. rulesBy turns {id: value} into {id: {field: value}}.
  withRules(rules,words){const out={};Object.keys(rules).forEach(k=>{out[k]={...rules[k],...(words[k]||{})};});return out;}
  withRulesByKey(rules,words){return rules.map(r=>({...r,...(words[r.key]||{})}));}
  // The rules of a story joined with its words, beat by beat (the conditions of the beats stay in lib/).
  storiesWithRules(rules,words){return rules.map(r=>{const w=words[r.key]||{},beats=w.beats||{};return {...r,...w,beats:r.beats.map(b=>({id:b.id,...(beats[b.id]||{})}))};});}
