  freeSpotNear(st,cx,cy,minDist=11){
    const taken=(st.placed||[]).map(q=>({x:Number(q.x)||0,y:Number(q.y)||0}));
    const clear=(x,y)=>taken.every(t=>Math.hypot((t.x-x)*1.4,t.y-y)>=minDist);
    const cx2=(v)=>Math.min(90,Math.max(8,v));
    const cy2=(v)=>Math.min(88,Math.max(14,v));
    const n=taken.length;
    for(let ring=1;ring<=6;ring++){
      const r=7+ring*5;
      for(let i=0;i<12;i++){
        const ang=((i*30)+n*37+ring*17)*Math.PI/180;
        const x=cx2(cx+Math.cos(ang)*r/1.4), y=cy2(cy+Math.sin(ang)*r);
        if(clear(x,y)){return {x:Math.round(x*10)/10,y:Math.round(y*10)/10};}
      }
    }
    return {x:cx2(cx+((n%5)-2)*6),y:cy2(cy+((n%3)+1)*5)};
  }
