  activeGuilds(placed){
    const out=[];
    this.guildDefs.forEach(d=>{
      const as=placed.filter(p=>p.type===d.types[0]);
      const bs=placed.filter(p=>p.type===d.types[1]);
      let best=null,bd=1e9;
      as.forEach(a=>bs.forEach(b=>{
        const dx=(a.x-b.x)*1.4, dy=a.y-b.y, dist=Math.hypot(dx,dy);
        if(dist<bd){bd=dist;best={a:a,b:b};}
      }));
      if(best&&bd<=22){ out.push({key:d.key,def:d,a:best.a,b:best.b}); }
    });
    return out;
  }
