  openBook(){this.setState({bookOpen:true,bookTab:this.state.bookTab||'elements',bookLeaf:0,bookDir:'fwd',headerMenuOpen:false},()=>this.later(()=>{const d=document.querySelector('[data-pg-dialog="book"]');if(d){d.focus();}},30));}
