      links:systems.links.map(link=>({kind:link.kind,label:link.label,fromType:link.a.type,toType:link.b.type})),
      journey:{done:journey.done,total:journey.total,currentKey:journey.current.key,completedKeys:journey.steps.filter(step=>step.done).map(step=>step.key)},
      sharedActs:st.sharedActs||0,
      completedChallenges:Object.keys(st.gatesPlayed||{}).filter(key=>!!st.gatesPlayed[key]),
      guildKeys:this.activeGuilds(st.placed||[]).map(g=>g.key),
