  // Measured, because the words decide: English fits a laptop window, German or Polish may not.
  fitHeader(){
    const root=document.documentElement,inner=document.querySelector('.pg-header-inner');
    if(!inner||this.state.viewportMode!=='desktop'){if(root.dataset.pgHeader){delete root.dataset.pgHeader;}return;}
    const brand=inner.querySelector('.pg-brand-title');
    // nothing pushed out of the window, and the name of the game shown whole
    const fits=()=>inner.scrollWidth<=inner.clientWidth+1&&(!brand||brand.scrollWidth<=brand.clientWidth+1);
    // the tools ease their size in; measure their final size, not the first frame
    root.dataset.pgHeaderMeasure='1';
    delete root.dataset.pgHeader;
    if(!fits()){root.dataset.pgHeader='tight';if(!fits()){root.dataset.pgHeader='tighter';}}
    delete root.dataset.pgHeaderMeasure;
  }
