    if(!text||!(this.state.placed||[]).length){this.setState({gardenFileNote:this.i18nText('gardenFile.nothing','There is no garden to save yet: place a first element.')});return;}
    const file=api.fileName(new Date(),!!this.WORKSHOP.enabled);
