      if(!result.ok){refuse(result.error);return;}
      if((this.state.placed||[]).length&&!window.confirm(this.i18nText('gardenFile.confirm','Loading replaces the garden in progress. Load the garden from the file?'))){return;}
      // the old garden must not be written back while the page reloads
