      try{localStorage.setItem(this.STORE,result.garden);}catch(_){this._replacingGarden=false;refuse('read');return;}
      this.setState({gardenFileNote:this.i18nText('gardenFile.loading','Loading the garden…')});
      setTimeout(()=>location.reload(),150);
