  giveToTable(){
    if(this.state.giveMode){ this.setState({giveMode:false,toast:null}); return; }
    if(!this.sharingUnlocked(this.state)){this.flash('The sharing table opens in the community act. Build the garden’s four living layers first.');return;}
    const eligible=(this.state.placed||[]).some(p=>this.elementGiftEligibility(p.id,this.state).eligible);
    if(!eligible){ this.flash('No established spare yet. '+this.firstGiftHint(this.state)); return; }
    this.setState({giveMode:true,plantType:null,selectedPlacedId:null,toast:'🌿 Choose an established duplicate. Your garden keeps one; the spare continues through the community. (Esc cancels)'});
  }
  reciprocityUnlocked(st=this.state){return this.rules.table.reciprocityUnlocked(st);}
  PROPAGABLE={compost:'a bucket of finished compost',mulch:'a share of the mulch pile',herbspiral:'rooted herb cuttings'};
  firstGiftHint(st=this.state){
    const season=st.season||'Summer';
    if(season==='Summer'&&(st.cherryPicks||0)>0){return 'In summer, the ripe cherries on your tree are the easiest first gift 🍒 — click a glowing cluster, then share from the basket.';}
    const b=st.basket||{};
    const bKey=Object.keys(b).find(k=>(b[k]||0)>0&&this.produceMeta[k]&&(!this.produceMeta[k].seasons||this.produceMeta[k].seasons.indexOf(season)>=0));
    if(bKey&&this.produceMeta[bKey]){return 'Your basket holds '+this.produceMeta[bKey].name.toLowerCase()+' — sharing harvest counts as a real gift. 🧺';}
    const prop=(st.placed||[]).find(p=>this.PROPAGABLE[p.type]&&(st.seasonTurns||0)-(p.placedAtTurn||0)>=1);
    if(prop){return 'Your established '+this.catalog[prop.type].name.toLowerCase()+' can spare '+this.PROPAGABLE[prop.type]+' — it stays in the garden while the gift travels.';}
    return 'Easiest first gifts: pick ripe produce in season, or let compost, mulch or herbs establish one seasonal turn — they can share a division without leaving your garden.';
  }
  // Only a genuine surplus can be given (lib/economy.js); why not is said here.
  elementGiftEligibility(id,st=this.state){
    const gift=this.rules.economy.giftable(st,id,this.sharingUnlocked(st),type=>!!this.cropDefs[type]);
    const item=(st.placed||[]).find(p=>p.id===id);
    if(gift.reason==='gone'){return {eligible:false,reason:'That element is no longer in the garden.'};}
    if(gift.reason==='closed'){return {eligible:false,reason:'Complete the four living layers before opening the community table.'};}
    if(gift.reason==='crop'){return {eligible:false,reason:'Share the harvested produce, not an unharvested crop.'};}
    if(gift.mode==='division'){
      if(!gift.eligible){return {eligible:false,reason:'Newly placed — let it establish through one seasonal turn, then it can spare '+this.PROPAGABLE[item.type]+'.'};}
      return {eligible:true,mode:'division',reason:'Established and abundant — it can spare '+this.PROPAGABLE[item.type]+' while staying in your garden.'};
    }
    if(gift.reason==='keep'){return {eligible:false,reason:'Keep one living example in the garden; only an established duplicate is surplus. '+this.firstGiftHint(st)};}
    if(!gift.eligible){return {eligible:false,reason:'This element is newly placed. Let it establish through one seasonal turn first.'};}
    return {eligible:true,reason:'Established duplicate available as a genuine spare.'};
  }
  // A gift never pays the giver (lib/economy.js).
  elementGiftReward(type,st=this.state){return this.rules.economy.giftReward();}
  // The one garden score shown on the resilience ring, the reflection card and the
  // downloadable certificate. It is derived from the garden state alone: the four
  // living layers carry most of the weight, then wild neighbours, active design
  // connections and genuine gifts.
  gardenScore(st=this.state,systems=this.gardenSystems(st)){
    const placed=st.placed||[];
    const wildlife=this.activeOf(placed).size;
    const guilds=this.activeGuilds(placed).length;
    return Math.min(100,Math.round(systems.average*.78+wildlife+(guilds/this.guildDefs.length)*5+(Math.min(st.given||0,6)/6)*7));
  }
  certificateStats(st=this.state){
    const systems=this.gardenSystems(st);
    const community=(st.sharedActs||0)>0;
    const wildlife=this.activeOf(st.placed||[]).size;
    const guilds=this.activeGuilds(st.placed||[]).length;
    const score=this.gardenScore(st,systems);
    const statusKey=score===0?'bare':score<40?'beginning':score<70?'connections':score<100?'flourishing':'rich';
    const status={bare:'A bare plot — ready to begin',beginning:'A living beginning',connections:'Connections taking shape',flourishing:'A flourishing design',rich:'A richly connected design'}[statusKey];
    const strengths=[],strengthKeys=[];
    const strength=(key,label)=>{strengths.push(label);strengthKeys.push(key);};
    if(systems.values.soil>=45){strength('completion.strength.soilLabel','Living soil');}
    if(systems.values.water>=45){strength('completion.strength.waterLabel','Water resilience');}
    if(systems.values.food>=45){strength('completion.strength.foodLabel','Food in relationships');}
    if(systems.values.habitat>=45){strength('completion.strength.habitatLabel','Connected habitat');}
    if(community){strength('completion.strength.sharing','Fair sharing');}
    return {score:score,status:status,statusKey:statusKey,wildlife:wildlife,guilds:guilds,given:st.given||0,strengths:strengths,strengthKeys:strengthKeys};
  }
  formatToday(){
    // The English copy uses British spelling, so English dates keep the day-month-year order.
    const locale=this.currentLocale(),options={day:'numeric',month:'long',year:'numeric'},i18n=this.i18n(),now=new Date();
    // a date formatter is slow to create; the text is kept for the rest of the day in this language
    const key=locale+'|'+now.getFullYear()+'-'+now.getMonth()+'-'+now.getDate();
    if(this._todayKey===key){return this._todayText;}
    let text;
    // through the runtime, so the page knows this date is already in the player's language
    if(locale!=='en'&&i18n&&typeof i18n.date==='function'){text=i18n.date(now,options);}
    else{try{text=new Intl.DateTimeFormat(locale==='en'?'en-GB':locale,options).format(now);}
    catch(_){text=now.toLocaleDateString('en-GB',options);}}
    this._todayKey=key;this._todayText=text;
    return text;
  }
