    [this._gameMusic,this._seasonMusic,this._reflectionMusic,this._gardenVoice].forEach(a=>{if(a){clearInterval(a._pgFade);a._pgFade=null;a.pause();try{a.currentTime=0;}catch(_){}if(a!==this._gardenVoice){a.volume=0;}}});
    this._gardenVoice=null;this._gardenVoiceId=null;this._musicMode=null;
    if(this._activeSfx){this._activeSfx.forEach(a=>{a.pause();});this._activeSfx.clear();}
