  flash(text){this.setState({toast:text});this.playSound('warning',{volume:.5,throttle:120});}
  playPlacement(type){
    if(type==='rain'||type==='birdbath'){this.playSound('water',{volume:.62});return;}
    if(type==='compost'||type==='mulch'){this.playSound('compost',{volume:.58});return;}
    if(this.cropDefs[type]||['appletree','hugel','herbspiral','pollinator','seedbank'].indexOf(type)>=0){this.playSound('plant',{volume:.58});return;}
    this.playSound('build',{volume:.58});
  }
  playSpecies(key){const k=(key==='winecap'||key==='oyster'||key==='field')?'mushroom':key;this.playSound(k,{volume:.48,throttle:30});}
