  removeSelected(){
    const id=this.state.selectedPlacedId;if(!id)return;
    const p=this.state.placed.find(x=>x.id===id);if(!p)return;
    const name=(this.catalog[p.type]||{}).name||'this element';
    const i18n=this.i18n();
    const localName=i18n?i18n.translateValue(name):name;
    const refund=p.paidMethod==='barter'
      ?(p.paidAmount+' '+(i18n?i18n.t(p.paidAmount===1?'common.share':'common.shares'):('share'+(p.paidAmount===1?'':'s'))))
      :(p.paidMethod==='buy'?('€'+p.paidAmount):(i18n?i18n.t('common.noPayment'):'no payment'));
    const removeMessage=i18n
      ?i18n.t('reset.removeConfirm',{name:localName,refund:refund})
      :('Remove '+name+' from the garden?\n\nRefund: '+refund+'. Wildlife or design connections that depend on it may leave until you rebuild their habitat.');
    if(!window.confirm(removeMessage)){return;}
    this.setState(s=>{
      const before=this.gardenSystems(s);
      const shares=s.shares+(p.paidMethod==='barter'?p.paidAmount:0);
      const budget=s.budget + (p.paidMethod==='buy'?p.paidAmount:0);
      const materials={...(s.materials||{})};
      (p.usedMaterials||[]).forEach(m=>{materials[m]=(materials[m]||0)+1;});
      let ns={...s, placed:s.placed.filter(x=>x.id!==id), shares:shares, budget:budget, materials:materials, selectedPlacedId:null, selectedType:null};
      const after=this.gardenSystems(ns);
      const changed=after.view.map((v,i)=>({key:v.key,name:v.name,delta:v.value-before.view[i].value,reason:v.reason})).filter(v=>v.delta!==0).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta))[0];
      const consequence=changed?(' '+changed.name+' changed by '+changed.delta+'. '+changed.reason):'';
      ns.toast='↩ '+name+' removed — '+refund+(p.paidMethod==='gift'?' was needed because it was a community gift.':' returned.')+consequence;
      if(changed){ns.lastSystemChange={text:'Removing '+name.toLowerCase()+' changed '+changed.name.toLowerCase()+' by '+changed.delta+' points. '+changed.reason,systemKey:changed.key,system:changed.name,delta:changed.delta,n:Date.now()};}
      return ns;
    });
  }

