        if(winP&&winP.s.indexOf(this.state.season||'Summer')<0){ this.flash('🗓️ '+c.name+' can’t go in now — '+winP.why+' Plantable: '+winP.s.map(k2=>this.seasonDefs[k2].emoji+' '+k2).join(' · ')); return; }
        if(this.cropDefs[type]&&!hasSeedbank){ this.flash('🌰 Plant a Seed bank first — every crop here starts as saved community seed.'); return; }
        if(this.state.plantType===type){ this.setState({plantType:null,movingPlacedId:null,toast:null}); return; }
        // Never fail silently on cost. Say what is short AND where it comes from —
